Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <cstring>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

const int MAX = 210;
const int INF = 0x3f3f3f3f;

int cap[MAX*MAX*2][MAX*MAX*2], flow[MAX*MAX*2][MAX*MAX*2];
int h[MAX*MAX*2], vh[MAX*MAX*2];
int n, t, src, dst;

inline int idx(int i, int j) { return (i-1)*n + j; }
inline bool valid(int x, int y) { return x>=1 && x<=n && y>=1 && y<=n; }

void add_edge(int u, int v, int c) {
    cap[u][v] += c;
}

int dfs(int u, int lim) {
    if (u == dst) return lim;
    int pushed = lim, delta, minH = n;
    for (int v = 0; v < n*n*2+2; ++v) {
        if (cap[u][v] - flow[u][v] > 0) {
            if (h[u] == h[v] + 1) {
                delta = dfs(v, min(pushed, cap[u][v] - flow[u][v]));
                flow[u][v] += delta;
                flow[v][u] -= delta;
                pushed -= delta;
                if (h[src] == n || pushed == 0) return lim - pushed;
            }
            minH = min(minH, h[v] + 1);
        }
    }
    if (pushed == lim) {
        vh[h[u]]--;
        vh[minH]++;
        if (vh[h[u]] == 0) h[src] = n;
        h[u] = minH;
    }
    return lim - pushed;
}

int max_flow() {
    if (src == dst) return INF;
    memset(flow, 0, sizeof(flow));
    memset(h, 0, sizeof(h));
    memset(vh, 0, sizeof(vh));
    int res = 0;
    while (h[src] != n*n*2+2) {
        res += dfs(src, INF);
    }
    return res;
}

struct Node { int x, y, d; };

int dist1[MAX][MAX], vis[MAX][MAX];
char g1[MAX][MAX], g2[MAX][MAX];
int sx, sy;
const int dx[] = {0,0,-1,1}, dy[] = {-1,1,0,0};

void bfs1() {
    queue<Node> q;
    Node cur = {sx, sy, 0}, nxt;
    q.push(cur);
    memset(dist1, 0x7f, sizeof(dist1));
    memset(vis, 0, sizeof(vis));
    vis[sx][sy] = 1;
    while (!q.empty()) {
        cur = q.front(); q.pop();
        dist1[cur.x][cur.y] = cur.d;
        if (cur.d > t) break;
        for (int k=0; k<4; ++k) {
            int nx = cur.x+dx[k], ny = cur.y+dy[k];
            if (valid(nx,ny) && g1[nx][ny]!='Y' && !vis[nx][ny]) {
                nxt = {nx, ny, cur.d+1};
                vis[nx][ny] = 1;
                q.push(nxt);
            }
        }
    }
}

void bfs2(int i, int j) {
    queue<Node> q;
    Node cur = {i, j, 0}, nxt;
    q.push(cur);
    memset(vis, 0, sizeof(vis));
    vis[i][j] = 1;
    while (!q.empty()) {
        cur = q.front(); q.pop();
        if (cur.d > t) break;
        if (dist1[cur.x][cur.y] < cur.d) continue;
        if (dist1[cur.x][cur.y] == cur.d && (g2[cur.x][cur.y]<'1' || g2[cur.x][cur.y]>'9')) continue;
        if (g2[cur.x][cur.y]>='1' && g2[cur.x][cur.y]<='9') {
            if (cur.x != i || cur.y != j)
                add_edge(idx(i,j), idx(cur.x,cur.y)+n*n, INF);
            if (dist1[cur.x][cur.y] == cur.d) continue;
        }
        for (int k=0; k<4; ++k) {
            int nx = cur.x+dx[k], ny = cur.y+dy[k];
            if (valid(nx,ny) && g1[nx][ny]!='Y' && !vis[nx][ny]) {
                nxt = {nx, ny, cur.d+1};
                vis[nx][ny] = 1;
                q.push(nxt);
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i=1; i<=n; ++i) scanf("%s", g1[i]+1);
    for (int i=1; i<=n; ++i) scanf("%s", g2[i]+1);

    src = 0; dst = 2*n*n+1;
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=n; ++j) {
            if (g1[i][j]>='1' && g1[i][j]<='9')
                add_edge(src, idx(i,j), g1[i][j]-'0');
            if (g1[i][j]=='Z') { sx=i; sy=j; }
        }
    }
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=n; ++j) {
            add_edge(idx(i,j), idx(i,j)+n*n, INF);
            if (g2[i][j]>='1' && g2[i][j]<='9')
                add_edge(idx(i,j)+n*n, dst, g2[i][j]-'0');
        }
    }
    bfs1();
    for (int i=1; i<=n; ++i)
        for (int j=1; j<=n; ++j)
            if (g1[i][j]>='1' && g1[i][j]<='9')
                bfs2(i,j);
    cout << max_flow() << endl;
    return 0;
}
